readonly visibleIds = computed(() => {
  const user = this.session.user();
  if (!user || this.steward()) return null;
  if (!this.roles.roles().some((r) => r.user === user && r.role === 'restricted')) return null;
  const ids = new Set<number>();
  const p = this.me();
  if (!p) return ids;
  ids.add(p.id);
  for (const c of this.crews.crews()) {
    const crew = [...(c.lead ? [c.lead.personId] : []), ...c.members.map((m) => m.personId)];
    if (crew.includes(p.id)) crew.forEach((id) => ids.add(id));
  }
  return ids;
});

/** A steward's dashboard: the sheet's PENDING and REVIEW claims and its overdue claims that count,
 *  counted; null when the signed-in user is not a steward. */
readonly dashboard = computed(() => {
  if (!this.steward()) return null;
  const claims = this.claims.claims();
  return {
    pending: claims.filter((c) => c.status === 'PENDING').length,
    review: claims.filter((c) => c.status === 'REVIEW').length,
    overdue: this.claims.live().filter((c) => this.claims.overdue(c)).length,
  };
});

/** A crew's due-total: the lead's and the members' due-totals as the people list shows them, added up,
 *  n/a skipped. */
crewDueCents(c: CrewView): bigint {
  const ids = new Set([...(c.lead ? [c.lead.personId] : []), ...c.members.map((m) => m.personId)]);
  let sum = 0n;
  for (const p of this.people.people()) {
    if (!ids.has(p.id)) continue;
    const d = this.dueCents(p);
    if (d !== null) sum += d;
}

/** Quick-add a DRAFT claim dated the sheet's today, with an empty note, for the person with the
 *  name, the server adding them with grade A first when the sheet has no one by it; an error
 *  message when refused. */
async quickAdd(name: string, amount: string): Promise<string | null> {
  if (!this.session.user() || !this.session.sheetId()) return 'Load a sheet first.';
  if (!name.trim()) return 'Enter a name.';
  const refused = this.check({ amount, date: '', note: '', corrects: '', ref: '', tags: '' });
  if (refused) return refused;
  const sid = this.session.sheetId()!;
  try {
    const added = await firstValueFrom(
      this.http.post<{ person: Person; personAdded: boolean; claim: Claim }>(
        `${this.url(sid)}/quick-claims`,
        { name: name.trim(), amount: amount.trim() },
        { headers: { 'X-User': this.session.user()! } },
      ),
    );
    if (this.session.sheetId() === sid) {
      this.people.people.update((ps) =>
        ps.some((p) => p.id === added.person.id)
          ? ps.map((p) => (p.id === added.person.id ? added.person : p))
          : [...ps, added.person],
      );
      this.claims.update((cs) => [added.claim, ...cs]);
    }
    return null;
  } catch (e) {
    return failed('add', e);
  }
}

/** Add and open a claim for each pasted line of name,amount,date,note, in order, for the person on the
 *  sheet with the name (a line matching a DRAFT updates and opens it instead); how many lines went
 *  through, or an error message when any line is refused (then the server changes nothing). */

